        content: "<template>\n  <div class=\"lissajous-backdrop-wrap\" :class=\"{ expanding: isStarted }\">\n    <canvas ref=\"canvasEl\" width=\"500\" height=\"500\" aria-label=\"Large background Lissajous harmonic orbit\"></canvas>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref, onMounted, onBeforeUnmount, watch } from 'vue'\n\nconst props = defineProps<{\n  isStarted?: boolean\n}>()\n\nconst canvasEl = ref<HTMLCanvasElement | null>(null)\nlet rafId = 0\nlet t = 0\nlet isVisible = false\nlet observer: IntersectionObserver | null = null\n\nconst render = () => {\n  const canvas = canvasEl.value\n  if (!canvas) {\n    rafId = requestAnimationFrame(render)\n    return\n  }\n\n  const ctx = canvas.getContext('2d')\n  if (!ctx) return\n\n  ctx.clearRect(0, 0, canvas.width, canvas.height)\n  \n  const cx = canvas.width / 2\n  const cy = canvas.height / 2\n  const R = 200\n\n  let delta: number\n  if (props.isStarted) {\n    delta = Math.PI / 2\n  } else {\n    t += 0.008\n    delta = t * 0.75\n  }\n\n  ctx.beginPath()\n  const a = 3\n  const b = 2\n\n  for (let i = 0; i <= 360; i += 1.5) {\n    const rad = (i * Math.PI) / 180\n    const x = cx + R * Math.sin(a * rad + delta)\n    const y = cy + R * Math.sin(b * rad)\n\n    if (i === 0) {\n      ctx.moveTo(x, y)\n    } else {\n      ctx.lineTo(x, y)\n    }\n  }\n\n  const grad = ctx.createLinearGradient(0, 0, canvas.width, canvas.height)\n  grad.addColorStop(0, 'rgba(174, 59, 139, 0.75)')\n  grad.addColorStop(0.5, 'rgba(225, 120, 136, 0.55)')\n  grad.addColorStop(1, 'rgba(245, 184, 209, 0.45)')\n\n  ctx.strokeStyle = grad\n  ctx.lineWidth = 1.6\n  ctx.stroke()\n\n  if (isVisible && !props.isStarted) {\n    rafId = requestAnimationFrame(render)\n  }\n}\n\nwatch(() => props.isStarted, (started) => {\n  if (started) {\n    render()\n  }\n})\n\nonMounted(() => {\n  if (canvasEl.value) {\n    observer = new IntersectionObserver((entries) => {\n      isVisible = entries[0].isIntersecting\n      if (isVisible) {\n        rafId = requestAnimationFrame(render)\n      } else {\n        if (rafId) cancelAnimationFrame(rafId)\n      }\n    })\n    observer.observe(canvasEl.value)\n  }\n})\n\nonBeforeUnmount(() => {\n  if (observer && canvasEl.value) {\n    observer.unobserve(canvasEl.value)\n    observer.disconnect()\n  }\n  if (rafId) cancelAnimationFrame(rafId)\n})\n</script>\n\n<style scoped>\n.lissajous-backdrop-wrap {\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  width: 460px;\n  height: 460px;\n  pointer-events: none;\n  filter: drop-shadow(0 0 30px rgba(174, 59, 139, 0.45));\n  transform: scale(1);\n  opacity: 1;\n  transition: transform 2.88s cubic-bezier(0.16, 1, 0.3, 1),\n              opacity 2.88s cubic-bezier(0.16, 1, 0.3, 1);\n  will-change: transform, opacity;\n}\n\n.lissajous-backdrop-wrap.expanding {\n  transform: scale(9.5);\n  opacity: 0;\n}\n\ncanvas {\n  width: 100%;\n  height: 100%;\n  display: block;\n}\n</style>\n"
